import React from 'react'
import type { Metadata } from 'next'
import { Toaster } from 'sonner'
import { AuthProvider } from '@/lib/AuthContext'
import { ThemeProvider } from '@/lib/ThemeContext'
import { RouteLoadingProvider } from '@/lib/RouteLoadingContext'
import TopLoadingBar from '@/components/layout/TopLoadingBar'
import './globals.css'

export const metadata: Metadata = {
  title: 'Kapit-Bisig',
  description: 'Kapit-Bisig Web Application',
  icons: {
    icon: '/images/Logo1.png',
    shortcut: '/images/Logo1.png',
    apple: '/images/Logo1.png',
  },
}

// Inline script to prevent theme FOUC (runs before React hydration)
const themeInitScript = `
(function(){
  try {
    var t = localStorage.getItem('kb-theme') || 'light';
    var s = localStorage.getItem('kb-text-size') || 'medium';
    var pathname = window.location.pathname || '/';
    var resolved = 'light';
    if (pathname !== '/login') {
      resolved = t;
      if (t === 'system') {
        resolved = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
      }
    }
    if (resolved === 'dark') document.documentElement.classList.add('dark');
    document.documentElement.setAttribute('data-theme', resolved);
    document.documentElement.setAttribute('data-text-size', s);
  } catch(e) {}
})();
`

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: themeInitScript }} />
      </head>
      <body className="antialiased">
        <ThemeProvider>
          <AuthProvider>
            <RouteLoadingProvider>
            <TopLoadingBar />
            {children}
            <Toaster
              position="top-right"
              toastOptions={{
                style: {
                  fontFamily: 'inherit',
                  borderRadius: '0.75rem',
                  fontSize: '0.875rem',
                },
              }}
              richColors
              closeButton
            />
            </RouteLoadingProvider>
          </AuthProvider>
        </ThemeProvider>
      </body>
    </html>
  )
}
